Dada la función siguiente, ¿qué llamada es válida?

func greet(_ name: String, from city: String) -> String {
    "Hola \(name) de \(city)"
}

¿Qué valor se imprime?

enum Planet: Int {
    case mercury = 1, venus, earth
}
print(Planet.earth.rawValue)

¿Qué ocurre con este código?

struct Counter {
    var n = 0
    mutating func inc() { n += 1 }
}
let c = Counter()
c.inc()

¿Cuál es la salida?

struct Counter {
    var n = 0
    mutating func inc() { n += 1 }
}
var a = Counter()
var b = a
b.inc()
print(a.n, b.n)

¿Qué valor se imprime?

var sum = 0
for i in 0..<5 {
    if i == 2 { continue }
    sum += i
}
print(sum)

